// 埋め込みフロントエンドアセット（scripts/build-embedded.mjs による自動生成。手編集禁止）
export const EMBEDDED_INDEX_HTML: string = "<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<meta name=\"theme-color\" content=\"#10305c\" />\n<meta name=\"description\" content=\"監査業務・証跡管理（Mirai Audit Workpaper）— 監査計画・証憑・調書・指摘・改善確認を証跡とともに管理します。\" />\n<meta name=\"robots\" content=\"noindex,nofollow\" />\n<title>監査業務・証跡管理 | Mirai Audit Workpaper</title>\n<style>\n:root{\n  /* ---- デザイントークン（監査・統治ブランド） ---- */\n  --navy:#10305c;\n  --navy-2:#1c4d86;\n  --blue:#2563a6;\n  --blue-strong:#1b4f8a;\n  --blue-light:#dcebf7;\n  --pale:#eef3f8;\n  --paper:#ffffff;\n  --line:#c7d4e2;\n  --ink:#182235;\n  --muted:#4c5a6c;\n  --ok:#14653e; --ok-bg:#e0f4e8;\n  --warn:#7a5200; --warn-bg:#fdf0d0;\n  --err:#9d2b23; --err-bg:#fbe5e2;\n  --info:#1c5a8c; --info-bg:#e0f0fb;\n  --purple:#523a99; --purple-bg:#efe9fb;\n  --gray:#52616f; --gray-bg:#e8edf2;\n  --focus:#2563a6;\n  --shadow-sm:0 1px 2px rgb(16 48 92 / .07);\n  --shadow-md:0 10px 28px rgb(16 48 92 / .12);\n  --radius:12px;\n  --radius-sm:8px;\n  --sidebar-w:240px;\n  --topbar-h:58px;\n  --font:\"Yu Gothic UI\",\"Hiragino Kaku Gothic ProN\",\"Meiryo\",system-ui,-apple-system,sans-serif;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;font-family:var(--font);color:var(--ink);background:linear-gradient(180deg,#f4f7fb 0%,#eaf0f6 100%);line-height:1.75;font-size:15px}\na:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid var(--focus);outline-offset:2px;border-radius:4px}\nbutton{background:linear-gradient(180deg,var(--blue) 0%,var(--blue-strong) 100%);color:#fff;border:0;border-radius:var(--radius-sm);padding:.5rem 1.05rem;font-size:.9rem;font-weight:600;cursor:pointer;transition:filter .15s,transform .1s,box-shadow .15s;box-shadow:0 1px 2px rgb(16 48 92 / .2)}\nbutton:hover{filter:brightness(1.07)}\nbutton:active{transform:translateY(1px)}\nbutton.sec{background:#e9eff5;color:var(--navy);box-shadow:none;border:1px solid var(--line)}\nbutton.sec:hover{background:#dde8f2}\nbutton.sec.on{background:var(--navy);color:#fff;border-color:var(--navy)}\nbutton.danger{background:linear-gradient(180deg,#b5453c 0%,#9d2b23 100%)}\nbutton[disabled]{opacity:.55;cursor:not-allowed}\ninput,textarea,select{width:100%;padding:.55rem .65rem;border:1px solid var(--line);border-radius:var(--radius-sm);font-size:.92rem;font-family:inherit;background:#fff;color:var(--ink);transition:border-color .15s,box-shadow .15s}\ninput:focus,textarea:focus,select:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgb(37 99 166 / .15)}\nlabel{display:block;font-size:.82rem;font-weight:600;color:var(--muted);margin:.7rem 0 .25rem}\na{color:var(--blue-strong);text-decoration:underline;text-underline-offset:2px}\na:hover{color:var(--navy)}\n.row{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:.9rem}\n.muted{color:var(--muted);font-size:.85rem}\n.error{color:var(--err);font-size:.88rem;font-weight:600;margin:.4rem 0 0}\n.hint{font-size:.8rem;color:var(--muted);margin-top:1rem;border-top:1px dashed var(--line);padding-top:.7rem}\n.actions{display:flex;gap:.55rem;flex-wrap:wrap;margin-top:.8rem;align-items:center}\n\n/* ===== レイアウト（トップバー + サイドバー + メイン） ===== */\n.app{min-height:100vh;display:flex;flex-direction:column}\n.topbar{background:linear-gradient(120deg,var(--navy) 0%,var(--navy-2) 55%,var(--blue) 100%);color:#fff;height:var(--topbar-h);padding:0 1.2rem;display:flex;align-items:center;gap:.9rem;box-shadow:0 2px 10px rgb(16 48 92 / .18);position:sticky;top:0;z-index:40}\n.topbar h1{font-size:1.08rem;margin:0;letter-spacing:.02em;display:flex;align-items:center;gap:.5rem;white-space:nowrap}\n.topbar h1::before{content:\"🧭\";font-size:1.05rem}\n.top-spacer{flex:1}\n.userchip{font-size:.84rem;color:#e6eef7;white-space:nowrap}\n.hamburger{display:none;background:#ffffff22;color:#fff;border:0;border-radius:var(--radius-sm);padding:.35rem .7rem;font-size:1.05rem;box-shadow:none}\n.layout{flex:1;display:flex;align-items:stretch;min-height:0}\n.sidebar{width:var(--sidebar-w);flex:0 0 var(--sidebar-w);background:var(--navy);color:#d8e6f4;padding:.8rem .6rem 1rem;display:flex;flex-direction:column;gap:.15rem;position:sticky;top:var(--topbar-h);height:calc(100vh - var(--topbar-h));overflow-y:auto;z-index:30}\n.side-group{font-size:.68rem;letter-spacing:.08em;color:#8fb0d6;margin:1rem .6rem .25rem;text-transform:uppercase}\n.side-group:first-child{margin-top:.2rem}\n.side-link{display:flex;align-items:center;gap:.6rem;color:#d8e6f4;text-decoration:none;font-weight:600;padding:.5rem .6rem;border-radius:var(--radius-sm);font-size:.9rem;cursor:pointer;transition:background .15s,color .15s;white-space:nowrap}\n.side-link .ic{font-size:1rem;flex:0 0 auto}\n.side-link:hover{background:#ffffff1c;color:#fff}\n.side-link.active{background:#ffffff2e;color:#fff;box-shadow:inset 3px 0 0 #7fb3e8}\n.side-foot{margin-top:auto;padding-top:.8rem;border-top:1px solid #ffffff1a}\n.side-toggle{background:#ffffff14;color:#d8e6f4;border:0;border-radius:var(--radius-sm);padding:.45rem .6rem;font-size:.85rem;cursor:pointer;width:100%;text-align:left}\n.side-toggle:hover{background:#ffffff26}\n.sidebar.collapsed{width:60px;flex-basis:60px}\n.sidebar.collapsed .side-link{justify-content:center;padding:.55rem 0}\n.sidebar.collapsed .side-link .lbl,.sidebar.collapsed .side-group,.sidebar.collapsed .side-toggle span{display:none}\n.sidebar.collapsed .side-toggle{text-align:center}\n.main{flex:1;min-width:0;padding:1.1rem clamp(.8rem,3vw,2.2rem) 3rem;max-width:1280px;margin:0 auto;width:100%}\n.breadcrumb{font-size:.82rem;color:var(--muted);margin-bottom:.7rem;display:flex;align-items:center;gap:.35rem;flex-wrap:wrap}\n.breadcrumb a{color:var(--blue-strong);cursor:pointer;text-decoration:none}\n.breadcrumb a:hover{text-decoration:underline}\n.breadcrumb .sep{color:#9db1c6}\n.breadcrumb .cur{color:var(--ink);font-weight:600}\n.card{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);padding:1.2rem 1.4rem;margin-bottom:1.1rem;box-shadow:var(--shadow-sm)}\n.card h2{margin:0 0 .8rem;color:var(--navy);font-size:1.15rem;border-bottom:2px solid var(--blue-light);padding-bottom:.45rem;display:flex;align-items:center;gap:.5rem}\n.card h3{color:var(--navy-2);font-size:1rem;margin:1.1rem 0 .5rem}\n.table-wrap{overflow-x:auto}\ntable{width:100%;border-collapse:collapse;font-size:.9rem}\nth,td{padding:.55rem .7rem;text-align:left;vertical-align:top;border-bottom:1px solid var(--line)}\nth{background:var(--navy);color:#fff;font-weight:600;white-space:nowrap}\ntr:nth-child(even) td{background:#f6f9fc}\ntbody tr:hover td{background:#eef5fb}\ntr.clickable{cursor:pointer}\n.badge{display:inline-block;border-radius:999px;padding:.14rem .65rem;font-size:.75rem;font-weight:700;letter-spacing:.02em;line-height:1.5;white-space:nowrap}\n.b-gray{background:var(--gray-bg);color:var(--gray)}\n.b-green{background:var(--ok-bg);color:var(--ok)}\n.b-amber{background:var(--warn-bg);color:var(--warn)}\n.b-red{background:var(--err-bg);color:var(--err)}\n.b-blue{background:var(--info-bg);color:var(--info)}\n.b-purple{background:var(--purple-bg);color:var(--purple)}\n.overdue{color:var(--err);font-weight:700}\n.mini{display:inline-block;border:1px solid var(--line);border-radius:6px;padding:.15rem .55rem;font-size:.78rem;color:var(--navy);cursor:pointer;background:#fff;box-shadow:none}\n.mini.on{background:var(--navy);color:#fff;border-color:var(--navy)}\n.filterbar{display:flex;gap:.4rem;flex-wrap:wrap;margin:.6rem 0 .9rem;align-items:center}\n.item-box{border:1px solid var(--line);border-radius:8px;padding:.8rem;margin:.6rem 0}\n.item-box .top{display:flex;justify-content:space-between;flex-wrap:wrap;gap:.4rem}\n.version-list{border-top:1px dashed var(--line);margin-top:.5rem;padding-top:.4rem}\n.version-list .v{font-size:.82rem;color:var(--muted);padding:.2rem 0;border-bottom:1px dotted var(--line)}\ndetails.version-details summary{cursor:pointer;color:var(--navy);font-size:.85rem;margin-top:.4rem}\n\n/* ===== ログイン ===== */\n.login-wrap{max-width:440px;margin:9vh auto 0;padding:0 1rem}\n.login-box{background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:2.2rem;box-shadow:var(--shadow-md)}\n.login-box h2{margin:0 0 .6rem;color:var(--navy);font-size:1.3rem;text-align:center}\n.login-box h2::before{content:\"🧭 \";display:block;font-size:1.6rem;margin-bottom:.4rem}\n.login-box .actions{justify-content:center}\n.login-box button{width:100%;padding:.65rem;font-size:.95rem}\n\n/* ===== モーダル ===== */\n.modal-backdrop{position:fixed;inset:0;background:rgb(16 48 92 / .45);display:flex;align-items:flex-start;justify-content:center;padding:6vh 1rem 2rem;z-index:100;overflow-y:auto}\n.modal{background:var(--paper);border-radius:14px;box-shadow:var(--shadow-md);width:100%;max-width:560px;animation:modalIn .16s ease-out}\n.modal.wide{max-width:760px}\n@keyframes modalIn{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}\n.modal-head{display:flex;justify-content:space-between;align-items:center;padding:1rem 1.3rem;border-bottom:1px solid var(--line)}\n.modal-head h3{margin:0;color:var(--navy);font-size:1.05rem}\n.modal-x{background:none;border:0;color:var(--muted);font-size:1.3rem;padding:0 .3rem;box-shadow:none}\n.modal-body{padding:1rem 1.3rem;max-height:64vh;overflow-y:auto}\n.modal-foot{display:flex;justify-content:flex-end;gap:.55rem;padding:1rem 1.3rem;border-top:1px solid var(--line)}\n.modal .error{margin:.5rem 0 0}\n\n/* ===== トースト ===== */\n#toast-root{position:fixed;right:1rem;bottom:1rem;z-index:200;display:flex;flex-direction:column;gap:.5rem}\n.toast{background:var(--navy);color:#fff;padding:.65rem 1rem;border-radius:var(--radius-sm);box-shadow:var(--shadow-md);font-size:.88rem;max-width:420px;animation:toastIn .18s ease-out}\n.toast.t-ok{background:#14653e}\n.toast.t-err{background:#9d2b23}\n@keyframes toastIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n\n/* ===== レスポンシブ ===== */\n@media(max-width:900px){\n  .hamburger{display:inline-block}\n  .sidebar{position:fixed;left:0;top:var(--topbar-h);bottom:0;transform:translateX(-105%);transition:transform .2s ease;width:var(--sidebar-w);flex-basis:auto;height:auto;box-shadow:var(--shadow-md)}\n  .sidebar.open{transform:translateX(0)}\n  .side-backdrop{position:fixed;inset:0;background:rgb(16 48 92 / .35);z-index:25;display:none}\n  .side-backdrop.show{display:block}\n  .userchip{max-width:160px;overflow:hidden;text-overflow:ellipsis}\n}\n@media(max-width:720px){\n  .topbar{padding:0 .8rem;gap:.5rem}\n  .topbar h1{font-size:.95rem}\n  .row{grid-template-columns:1fr}\n  .main{padding:1rem .9rem 2.5rem}\n  table{display:block;overflow-x:auto;white-space:nowrap}\n  .actions button{flex:1 1 auto}\n}\n@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n@media print{\n  .topbar,.sidebar,.breadcrumb,.actions,.filterbar,.modal-backdrop{display:none!important}\n  body{background:#fff}\n  .card{border:1px solid #999;box-shadow:none;break-inside:avoid}\n  .layout{display:block}\n  a{text-decoration:none;color:var(--ink)}\n}\n</style>\n</head>\n<body>\n<div id=\"app\" class=\"app\"></div>\n<div id=\"modal-root\"></div>\n<div id=\"toast-root\"></div>\n<script>\n// ===================== API クライアント =====================\nasync function api(path, opts={}){\n  const res = await fetch(path, {...opts, headers:{\"Content-Type\":\"application/json\", ...(opts.headers||{})}, credentials:\"same-origin\"});\n  if(!res.ok){ let m=`エラー (${res.status})`; try{const b=await res.json(); if(b.error?.message)m=b.error.message;}catch{} throw new Error(m); }\n  if(res.status===204) return null; return res.json();\n}\nconst A = {\n  login:(e,p)=>api(\"/api/auth/login\",{method:\"POST\",body:JSON.stringify({email:e,password:p})}),\n  logout:()=>api(\"/api/auth/logout\",{method:\"POST\"}),\n  changePassword:(cur,next)=>api(\"/api/auth/password\",{method:\"POST\",body:JSON.stringify({current_password:cur,new_password:next})}),\n  health:()=>api(\"/api/health\"),\n  me:()=>api(\"/api/me\"),\n  users:()=>api(\"/api/users\"),\n  plans:()=>api(\"/api/plans\"),\n  createPlan:(d)=>api(\"/api/plans\",{method:\"POST\",body:JSON.stringify(d)}),\n  plan:(id)=>api(`/api/plans/${id}`),\n  updatePlan:(id,d)=>api(`/api/plans/${id}`,{method:\"PUT\",body:JSON.stringify(d)}),\n  submitPlan:(id)=>api(`/api/plans/${id}/submit`,{method:\"POST\"}),\n  approvePlan:(id)=>api(`/api/plans/${id}/approve`,{method:\"POST\"}),\n  rejectPlan:(id)=>api(`/api/plans/${id}/reject`,{method:\"POST\"}),\n  engagements:()=>api(\"/api/engagements\"),\n  createEngagement:(d)=>api(\"/api/engagements\",{method:\"POST\",body:JSON.stringify(d)}),\n  engagement:(id)=>api(`/api/engagements/${id}`),\n  updateEngagement:(id,d)=>api(`/api/engagements/${id}`,{method:\"PUT\",body:JSON.stringify(d)}),\n  setEngStatus:(id,s)=>api(`/api/engagements/${id}/status`,{method:\"POST\",body:JSON.stringify({status:s})}),\n  requests:(q=\"\")=>api(`/api/requests${q}`),\n  createRequest:(eid,d)=>api(`/api/engagements/${eid}/requests`,{method:\"POST\",body:JSON.stringify(d)}),\n  sendRequest:(id)=>api(`/api/requests/${id}/send`,{method:\"POST\"}),\n  receiveRequest:(id)=>api(`/api/requests/${id}/receive`,{method:\"POST\"}),\n  returnRequest:(id)=>api(`/api/requests/${id}/return`,{method:\"POST\"}),\n  closeRequest:(id)=>api(`/api/requests/${id}/close`,{method:\"POST\"}),\n  submitEvidence:(rid,d)=>api(`/api/requests/${rid}/submissions`,{method:\"POST\",body:JSON.stringify(d)}),\n  workpapers:(eid)=>api(`/api/engagements/${eid}/workpapers`),\n  createWorkpaper:(eid,d)=>api(`/api/engagements/${eid}/workpapers`,{method:\"POST\",body:JSON.stringify(d)}),\n  updateWorkpaper:(id,d)=>api(`/api/workpapers/${id}`,{method:\"PUT\",body:JSON.stringify(d)}),\n  reqReview:(id)=>api(`/api/workpapers/${id}/review`,{method:\"POST\"}),\n  approveWorkpaper:(id)=>api(`/api/workpapers/${id}/approve`,{method:\"POST\"}),\n  returnWorkpaper:(id)=>api(`/api/workpapers/${id}/return`,{method:\"POST\"}),\n  findings:(eid)=>api(`/api/engagements/${eid}/findings`),\n  createFinding:(eid,d)=>api(`/api/engagements/${eid}/findings`,{method:\"POST\",body:JSON.stringify(d)}),\n  respondFinding:(id,d)=>api(`/api/findings/${id}/responses`,{method:\"POST\",body:JSON.stringify(d)}),\n  confirmFinding:(id,d)=>api(`/api/findings/${id}/confirm`,{method:\"POST\",body:JSON.stringify(d)}),\n  createRemediation:(fid,d)=>api(`/api/findings/${fid}/remediations`,{method:\"POST\",body:JSON.stringify(d)}),\n  verifyRemediation:(id,d)=>api(`/api/remediations/${id}/verify`,{method:\"POST\",body:JSON.stringify(d)}),\n  auditEvents:(q=\"\")=>api(`/api/audit-events?${q}`),\n};\n\n// ===================== 定数・表示辞書 =====================\nconst ROLE={auditor:\"監査役\",audit_committee:\"監査役会\",general_affairs:\"総務部\",auditee:\"被監査部門\",admin:\"システム管理者\"};\nconst BADGE={draft:\"b-gray\",pending_approval:\"b-amber\",approved:\"b-green\",rejected:\"b-red\",in_progress:\"b-blue\",review:\"b-purple\",reported:\"b-blue\",closed:\"b-green\",sent:\"b-blue\",partial:\"b-amber\",received:\"b-green\",returned:\"b-red\",review_requested:\"b-amber\",final:\"b-green\",fact_check:\"b-amber\",confirmed:\"b-blue\",remediated:\"b-purple\",rechecked:\"b-amber\",completed:\"b-green\",planned:\"b-gray\",submitted:\"b-blue\",verified:\"b-green\"};\nconst ST={ // 状態の日本語ラベル（F-10 対応）\n  draft:\"下書き\",pending_approval:\"承認申請中\",approved:\"承認済み\",rejected:\"却下\",\n  in_progress:\"実施中\",review:\"レビュー中\",reported:\"報告済み\",closed:\"締切・完了\",\n  sent:\"送付済\",partial:\"一部受領\",received:\"受領済\",returned:\"差戻し\",\n  review_requested:\"レビュー依頼中\",final:\"確定\",fact_check:\"事実確認中\",confirmed:\"確定\",\n  remediated:\"是正中\",rechecked:\"再確認中\",completed:\"完了\",reissued:\"再指摘\",\n  planned:\"計画\",submitted:\"提出済\",verified:\"検証済\",accepted:\"受領\",\n};\nconst TASK_TYPE={engagement:\"案件\",request:\"依頼\",workpaper:\"調書\",finding:\"指摘\",remediation:\"是正\"};\nconst ACTION_JA={ // 監査ログの操作名（F-06 対応）\n  login:\"ログイン\",logout:\"ログアウト\",login_failed:\"ログイン失敗\",\n  password_changed:\"パスワード変更\",password_change_failed:\"パスワード変更失敗\",\n  plan_created:\"計画作成\",plan_updated:\"計画更新\",plan_submitted:\"承認申請\",plan_approved:\"計画承認\",plan_rejected:\"計画却下\",\n  engagement_created:\"案件作成\",engagement_updated:\"案件更新\",engagement_status:\"案件状態変更\",engagement_access_denied:\"案件アクセス拒否\",\n  request_created:\"依頼作成\",request_sent:\"依頼送付\",request_received:\"依頼受領\",request_returned:\"依頼差戻し\",request_closed:\"依頼締切\",\n  submission_created:\"証憑提出\",submission_denied:\"提出拒否\",\n  workpaper_created:\"調書作成\",workpaper_updated:\"調書更新\",workpaper_review_requested:\"レビュー依頼\",workpaper_approved:\"調書確定\",workpaper_returned:\"調書差戻し\",\n  finding_created:\"指摘作成\",finding_response:\"指摘回答\",finding_confirmed:\"指摘確定\",\n  remediation_created:\"是正登録\",remediation_verified:\"是正確認\",\n  permission_denied:\"権限拒否\",\n};\nconst OBJ_JA={auth:\"認証\",permission:\"権限\",audit_plan:\"監査計画\",engagement:\"案件\",evidence_request:\"証憑依頼\",submission:\"証憑提出\",workpaper:\"調書\",finding:\"指摘\",remediation:\"是正\"};\nconst RESULT_JA={success:\"成功\",denied:\"拒否\",failed:\"失敗\"};\n// ロール別UI表示権限（サーバ側の権限判定は変更しない。表示出し分け専用）\nconst UI_PERM={\n  auditor:[\"plan:view\",\"plan:create\",\"plan:update\",\"engagement:view\",\"engagement:create\",\"request:view\",\"request:create\",\"request:send\",\"workpaper:create\",\"finding:create\",\"remediation:create\",\"auditlog:view\",\"users:view\"],\n  audit_committee:[\"plan:view\",\"engagement:view\",\"request:view\",\"auditlog:view\"],\n  general_affairs:[\"plan:view\",\"engagement:view\",\"engagement:update\",\"request:view\",\"request:create\",\"request:send\"],\n  auditee:[\"engagement:view\",\"request:view\",\"request:submit\",\"finding:respond\"],\n  admin:[\"auditlog:view\",\"users:view\"],\n};\nconst uiCan=(role,perm)=>(UI_PERM[role]||[]).includes(perm);\nconst esc=s=>String(s??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst dateFmt=s=>s?new Date(s).toLocaleString(\"ja-JP\"):\"—\";\nconst dateOnly=s=>s?new Date(s).toLocaleDateString(\"ja-JP\"):\"—\";\nconst todayStr=()=>new Date().toISOString().slice(0,10);\nconst isOverdue=d=>!!d && d.slice(0,10) < todayStr();\nconst stLabel=s=>ST[s]||s;\nconst badge=s=>`<span class=\"badge ${BADGE[s]||\"b-gray\"}\">${esc(stLabel(s))}</span>`;\nconst sevLabel=s=>s===\"high\"?\"高\":s===\"medium\"?\"中\":s===\"low\"?\"低\":s;\nconst fmtDue=d=>{ if(!d) return \"—\"; const ov=isOverdue(d); return `<span class=\"${ov?\"overdue\":\"\"}\">${dateOnly(d)}${ov?\"（期限超過）\":\"\"}</span>`; };\n\n// ===================== 状態・ルーティング =====================\nlet state={me:null};\nconst cache={plans:[],planDetail:null,engs:[],engDetail:null,requests:[],events:[],users:[],engFilter:null};\nlet renderSeq=0;\nconst app=document.getElementById(\"app\");\nconst modalRoot=document.getElementById(\"modal-root\");\nconst toastRoot=document.getElementById(\"toast-root\");\nlet modalState=null;\n\nfunction parseHash(){\n  const raw=(location.hash||\"\").replace(/^#\\/?/,\"\");\n  const parts=raw.split(\"/\").filter(Boolean);\n  const r={view:\"home\",id:null,tab:null,extra:null};\n  if(parts[0]===\"plans\"){r.view=\"plans\";r.id=parts[1]||null;}\n  else if(parts[0]===\"engagements\"){r.view=\"engagements\";r.id=parts[1]||null;r.tab=parts[2]||null;}\n  else if(parts[0]===\"requests\"){r.view=\"requests\";r.extra=parts[1]||null;}\n  else if(parts[0]===\"auditlog\"){r.view=\"auditlog\";}\n  return r;\n}\nfunction buildHash(view,id,tab,extra){let h=\"#/\"+view;if(id)h+=\"/\"+id;if(tab)h+=\"/\"+tab;if(extra&&!id&&!tab)h+=\"/\"+extra;return h;}\nfunction navigate(view,id,tab,extra){\n  const h=buildHash(view,id,tab,extra);\n  closeModal(); // 画面遷移時のみモーダルを閉じる（データ再描画では閉じない）\n  if(location.hash===h){render();}else{location.hash=h;}\n}\n\nfunction toast(msg,type=\"ok\"){const el=document.createElement(\"div\");el.className=`toast t-${type}`;el.textContent=msg;toastRoot.appendChild(el);setTimeout(()=>{el.remove();},4200);}\n\n// ===================== モーダル =====================\nfunction openModal({title,body,okLabel=\"実行\",okClass=\"\",onOk=null,wide=false}){\n  modalState={onOk};\n  modalRoot.innerHTML=`\n    <div class=\"modal-backdrop\" data-modal=\"close\">\n      <div class=\"modal ${wide?\"wide\":\"\"}\" role=\"dialog\" aria-modal=\"true\" aria-label=\"${esc(title)}\">\n        <div class=\"modal-head\"><h3>${esc(title)}</h3><button class=\"modal-x sec\" data-modal=\"close\" aria-label=\"閉じる\">×</button></div>\n        <div class=\"modal-body\">${body}<div id=\"modal-err\" class=\"error\"></div></div>\n        <div class=\"modal-foot\">\n          <button class=\"sec\" data-modal=\"close\">キャンセル</button>\n          <button id=\"modal-ok\" class=\"${okClass}\">${esc(okLabel)}</button>\n        </div>\n      </div>\n    </div>`;\n  const okBtn=document.getElementById(\"modal-ok\");\n  okBtn.onclick=()=>{ if(modalState?.onOk) modalState.onOk(okBtn); };\n  const bodyEl=modalRoot.querySelector(\".modal-body\");\n  bodyEl.addEventListener(\"keydown\",ev=>{\n    if(ev.key===\"Enter\" && ev.target.tagName!==\"TEXTAREA\" && !ev.target.matches(\"button\")){ev.preventDefault();okBtn.click();}\n  });\n  const first=bodyEl.querySelector(\"input,select,textarea\"); if(first) setTimeout(()=>first.focus(),50);\n}\nfunction closeModal(){modalRoot.innerHTML=\"\";modalState=null;}\nfunction modalErr(msg){const el=document.getElementById(\"modal-err\");if(el)el.textContent=msg||\"\";}\nfunction confirmModal(message,onYes,yesLabel=\"実行する\"){\n  openModal({title:\"確認\",body:`<p style=\"margin:.2rem 0\">${esc(message)}</p>`,okLabel:yesLabel,okClass:\"danger\",onOk:()=>{closeModal();onYes();}});\n}\n\n// ===================== トップバー・サイドバー・パンくず =====================\nfunction topbarHTML(me){\n  const name=esc(me.user.name), role=ROLE[me.user.role]||me.user.role, dept=esc(me.user.department);\n  return `\n  <header class=\"topbar\">\n    <button class=\"hamburger\" data-act=\"hamburger\" aria-label=\"メニューを開く\">☰</button>\n    <h1>監査業務・証跡管理</h1>\n    <div class=\"top-spacer\"></div>\n    <span class=\"userchip\">${name}（${esc(role)} / ${dept}）</span>\n    <button class=\"sec\" data-act=\"password\">🔑 パスワード変更</button>\n    <button class=\"sec\" data-act=\"logout\">ログアウト</button>\n  </header>`;\n}\nfunction sidebarHTML(role,route){\n  const lnk=(v,l,ic,cond)=>{ if(!cond) return \"\"; const active=route.view===v?\"active\":\"\"; return `<a class=\"side-link ${active}\" data-nav=\"${v}\" title=\"${l}\"><span class=\"ic\">${ic}</span><span class=\"lbl\">${l}</span></a>`; };\n  const collapsed=localStorage.getItem(\"maw.sidebar.collapsed\")===\"1\"?\"collapsed\":\"\";\n  return `\n  <aside class=\"sidebar ${collapsed}\" id=\"sidebar\" aria-label=\"メインメニュー\">\n    <div class=\"side-group\">業務</div>\n    ${lnk(\"home\",\"ホーム\",\"🏠\",true)}\n    ${lnk(\"plans\",\"監査計画\",\"📋\",uiCan(role,\"plan:view\"))}\n    ${lnk(\"engagements\",\"監査案件\",\"📁\",uiCan(role,\"engagement:view\"))}\n    ${lnk(\"requests\",\"証憑依頼\",\"📩\",uiCan(role,\"request:view\"))}\n    <div class=\"side-group\">管理</div>\n    ${lnk(\"auditlog\",\"監査ログ\",\"🕓\",uiCan(role,\"auditlog:view\"))}\n    <div class=\"side-foot\">\n      <button class=\"side-toggle\" data-act=\"collapse-sidebar\" title=\"サイドバーを折りたたむ\"><span>◀ 折りたたむ</span><span style=\"display:none\">▶</span></button>\n    </div>\n  </aside>\n  <div class=\"side-backdrop\" id=\"side-backdrop\" data-act=\"hamburger\"></div>`;\n}\nfunction breadcrumbHTML(route){\n  const parts=[`<a data-nav=\"home\">ホーム</a>`];\n  const add=(label,nav,id)=>{parts.push(`<span class=\"sep\">›</span><a data-nav=\"${nav}\" ${id?`data-id=\"${esc(id)}\"`:\"\"}>${esc(label)}</a>`);};\n  const addCur=label=>{parts.push(`<span class=\"sep\">›</span><span class=\"cur\">${esc(label)}</span>`);};\n  const tabJA={requests:\"証憑依頼\",workpapers:\"監査調書\",findings:\"指摘・是正\"};\n  if(route.view===\"plans\"){add(\"監査計画\",\"plans\"); if(route.id) addCur(cache.planDetail?.plan?.title||\"計画詳細\");}\n  else if(route.view===\"engagements\"){add(\"監査案件\",\"engagements\"); if(route.id){ addCur(cache.engDetail?.engagement?.engagement_no||\"案件\"); if(route.tab) addCur(tabJA[route.tab]||route.tab);}}\n  else if(route.view===\"engagement\"){add(\"監査案件\",\"engagements\"); addCur(cache.engDetail?.engagement?.engagement_no||\"案件\"); if(route.tab) addCur(tabJA[route.tab]||route.tab);}\n  else if(route.view===\"requests\"){add(\"証憑依頼\",\"requests\");}\n  else if(route.view===\"auditlog\"){add(\"監査ログ\",\"auditlog\");}\n  else {addCur(\"ホーム\");}\n  return `<div class=\"breadcrumb\">${parts.join(\"\")}</div>`;\n}\n\n// ===================== 描画 =====================\nasync function refreshMe(){\n  try{ state.me=await A.me(); render(); }\n  catch{ state.me=null; render(); }\n}\nfunction render(){\n  renderSeq++;\n  if(!state.me){ closeModal(); renderLogin(); return; }\n  const me=state.me, role=me.user.role;\n  const route=parseHash();\n  app.innerHTML=`${topbarHTML(me)}\n    <div class=\"layout\">${sidebarHTML(role,route)}\n    <main class=\"main\" id=\"main\">${breadcrumbHTML(route)}${viewHTML(route)}</main>\n    </div>`;\n  loadViewData(route);\n}\nfunction viewHTML(route){\n  const r=route;\n  if(r.view===\"plans\" && r.id) return planHTML(r.id);\n  if(r.view===\"plans\") return plansHTML();\n  if(r.view===\"engagements\" && r.id) return engagementHTML(r.id, r.tab);\n  if(r.view===\"engagements\") return engagementsHTML();\n  if(r.view===\"requests\") return requestsHTML(r.extra);\n  if(r.view===\"auditlog\") return auditLogHTML();\n  return homeHTML();\n}\n// 各ビューのデータ取得（取得後に再描画）\nfunction loadViewData(route){\n  const seq=renderSeq;\n  const done=()=>{ if(seq===renderSeq) render(); };\n  try{\n    if(route.view===\"plans\" && route.id) A.plan(route.id).then(x=>{cache.planDetail=x;done();}).catch(e=>{toast(e.message,\"err\");});\n    else if(route.view===\"plans\") A.plans().then(x=>{cache.plans=x.plans;done();}).catch(e=>toast(e.message,\"err\"));\n    else if(route.view===\"engagements\" && !route.id) A.engagements().then(x=>{cache.engs=x.engagements;done();}).catch(e=>toast(e.message,\"err\"));\n    // 案件作成フォーム用に計画も取得（案件一覧表示とは独立。権限のあるロールのみ）\n    if(route.view===\"engagements\" && !route.id && uiCan(state.me.user.role,\"plan:view\"))\n      A.plans().then(x=>{cache.plans=x.plans; if(seq===renderSeq) render();}).catch(()=>{});\n    else if(route.view===\"engagements\" && route.id) A.engagement(route.id).then(x=>{cache.engDetail=x;done();}).catch(e=>{toast(e.message,\"err\");});\n    else if(route.view===\"requests\") A.requests(route.extra?`?status=${encodeURIComponent(route.extra)}`:\"\").then(x=>{cache.requests=x.requests;done();}).catch(e=>toast(e.message,\"err\"));\n    else if(route.view===\"auditlog\"){\n      Promise.all([A.auditEvents(), uiCan(state.me.user.role,\"users:view\")?A.users():Promise.resolve(null)])\n        .then(([ev,us])=>{cache.events=ev.events; if(us) cache.users=us.users; done();})\n        .catch(e=>toast(e.message,\"err\"));\n    }\n  }catch(e){ toast(e.message,\"err\"); }\n}\n\n// ===================== ホーム =====================\nfunction homeHTML(){\n  const me=state.me, role=me.user.role;\n  const tasks=me.tasks||[];\n  const rows=tasks.map(t=>{\n    const nav=t.engagement_id?` data-nav=\"engagements\" data-id=\"${esc(t.engagement_id)}\" data-tab=\"requests\"`:\"\";\n    const rowCls=t.engagement_id?\"clickable\":\"\";\n    return `<tr class=\"${rowCls}\"${nav}><td>${TASK_TYPE[t.type]||esc(t.type)}</td><td>${esc(t.title)}</td><td>${badge(t.status)}</td><td>${fmtDue(t.due_at)}</td></tr>`;\n  }).join(\"\");\n  return `\n    <div class=\"card\"><h2>自分のタスク・期限</h2>\n      ${tasks.length?`<div class=\"table-wrap\"><table><tr><th>種別</th><th>内容</th><th>状態</th><th>期限</th></tr>${rows}</table></div>\n      <p class=\"muted\">行をクリックすると案件詳細（証憑依頼）を開きます。</p>`\n      :`<p class=\"muted\">現在、割り当てられたタスクはありません。</p>`}\n    </div>\n    <div class=\"card\"><h2>監査の全体像</h2>\n      <p class=\"muted\">年度監査計画 → 個別監査 → 証憑依頼・受領 → 監査手続・調書 → レビュー・承認 → 指摘・改善 → 完了・保存</p>\n      <div class=\"actions\">\n        ${uiCan(role,\"plan:view\")?`<button data-nav=\"plans\">監査計画へ</button>`:\"\"}\n        ${uiCan(role,\"engagement:view\")?`<button class=\"sec\" data-nav=\"engagements\">監査案件一覧へ</button>`:\"\"}\n      </div>\n    </div>`;\n}\n\n// ===================== 監査計画 =====================\nfunction plansHTML(){\n  const role=state.me.user.role;\n  const rows=cache.plans.map(p=>`<tr class=\"clickable\" data-nav=\"plans\" data-id=\"${esc(p.id)}\">\n    <td>${esc(p.fiscal_year)}</td><td>${esc(p.title)}</td>\n    <td>${badge(p.status)}</td><td>v${esc(p.version)}</td><td>${dateFmt(p.updated_at)}</td></tr>`).join(\"\");\n  return `<div class=\"card\"><h2>年度監査計画</h2>\n    ${uiCan(role,\"plan:create\")?`<div class=\"actions\"><button data-act=\"plan-create\">新規計画</button></div>`:\"\"}\n    <div class=\"table-wrap\"><table><tr><th>年度</th><th>計画名</th><th>状態</th><th>版</th><th>更新日</th></tr>\n    ${rows||`<tr><td colspan=\"5\" class=\"muted\">計画がありません</td></tr>`}</table></div></div>`;\n}\nfunction planHTML(id){\n  const p=cache.planDetail?.plan; if(!p) return loadingCard();\n  const role=state.me.user.role;\n  const engs=cache.planDetail.engagements||[];\n  const actions=[];\n  if(p.status===\"draft\"&&uiCan(role,\"plan:create\")) actions.push(`<button data-act=\"plan-submit\" data-id=\"${esc(p.id)}\">承認申請</button>`);\n  if(p.status===\"pending_approval\"&&role===\"audit_committee\"){\n    actions.push(`<button data-act=\"plan-approve\" data-id=\"${esc(p.id)}\">承認</button>`);\n    actions.push(`<button class=\"sec\" data-act=\"plan-reject\" data-id=\"${esc(p.id)}\">却下</button>`);\n  }\n  if(p.status===\"rejected\"&&uiCan(role,\"plan:create\")) actions.push(`<button data-act=\"plan-submit\" data-id=\"${esc(p.id)}\">再申請</button>`);\n  if(uiCan(role,\"plan:update\")&&p.status!==\"approved\") actions.push(`<button class=\"sec\" data-act=\"plan-edit\" data-id=\"${esc(p.id)}\">編集</button>`);\n  if(p.status===\"approved\") actions.push(`<p class=\"muted\" style=\"margin:.4rem 0\">承認済みのため編集できません。次年度版として新規作成してください。</p>`);\n  return `<div class=\"card\"><h2>${esc(p.fiscal_year)}年度 ${esc(p.title)}</h2>\n    <p class=\"muted\">状態: ${badge(p.status)}（v${esc(p.version)}）</p>\n    <p>${esc(p.policy)||\"（方針未記載）\"}</p>\n    ${actions.length?`<div class=\"actions\">${actions.join(\"\")}</div>`:\"\"}\n    <h3 style=\"margin-top:1rem\">関連案件</h3>\n    <div class=\"table-wrap\"><table><tr><th>案件番号</th><th>名称</th><th>対象部門</th><th>状態</th></tr>${\n      engs.map(e=>`<tr class=\"clickable\" data-nav=\"engagements\" data-id=\"${esc(e.id)}\"><td>${esc(e.engagement_no)}</td><td>${esc(e.title)}</td><td>${esc(e.department)}</td><td>${badge(e.status)}</td></tr>`).join(\"\")\n    }${engs.length?\"\":`<tr><td colspan=\"4\" class=\"muted\">案件がありません</td></tr>`}</table></div></div>`;\n}\n\n// ===================== 監査案件 =====================\nfunction engagementsHTML(){\n  const role=state.me.user.role;\n  const engs=cache.engs||[];\n  const statuses=[\"draft\",\"pending_approval\",\"in_progress\",\"review\",\"reported\",\"closed\"];\n  const chips=[`<button class=\"mini ${!cache.engFilter?\"on\":\"\"}\" data-act=\"eng-filter\" data-status=\"\">すべて</button>`\n    +statuses.map(s=>`<button class=\"mini ${cache.engFilter===s?\"on\":\"\"}\" data-act=\"eng-filter\" data-status=\"${s}\">${stLabel(s)}</button>`).join(\"\")];\n  const shown=cache.engFilter?engs.filter(e=>e.status===cache.engFilter):engs;\n  const rows=shown.map(e=>`<tr class=\"clickable\" data-nav=\"engagements\" data-id=\"${esc(e.id)}\">\n    <td>${esc(e.engagement_no)}</td><td>${esc(e.title)}</td><td>${esc(e.department)}</td>\n    <td><span class=\"badge b-purple\">${esc(e.classification)}</span></td><td>${badge(e.status)}</td></tr>`).join(\"\");\n  return `<div class=\"card\"><h2>監査案件</h2>\n    ${uiCan(role,\"engagement:create\")?`<div class=\"actions\"><button data-act=\"eng-create\">新規案件</button></div>`:\"\"}\n    <div class=\"filterbar\">${chips.join(\"\")}</div>\n    <div class=\"table-wrap\"><table><tr><th>案件番号</th><th>名称</th><th>対象部門</th><th>機密</th><th>状態</th></tr>\n    ${rows||`<tr><td colspan=\"5\" class=\"muted\">案件がありません</td></tr>`}</table></div></div>`;\n}\nfunction engagementHTML(id,tab){\n  const d=cache.engDetail; if(!d) return loadingCard();\n  const e=d.engagement, role=state.me.user.role;\n  const canEdit=role===\"auditor\"||role===\"general_affairs\";\n  const actions=[];\n  if(e.status===\"draft\"&&role===\"auditor\") actions.push(`<button data-act=\"eng-status\" data-id=\"${esc(e.id)}\" data-status=\"pending_approval\">承認申請</button>`);\n  if(e.status===\"pending_approval\"&&role===\"audit_committee\") actions.push(`<button data-act=\"eng-status\" data-id=\"${esc(e.id)}\" data-status=\"in_progress\">開始</button>`);\n  if(e.status===\"in_progress\"&&(role===\"auditor\"||role===\"general_affairs\")) actions.push(`<button class=\"sec\" data-act=\"eng-status\" data-id=\"${esc(e.id)}\" data-status=\"review\">レビューへ</button>`);\n  if(e.status===\"review\"&&role===\"audit_committee\") actions.push(`<button data-act=\"eng-status\" data-id=\"${esc(e.id)}\" data-status=\"reported\">報告確定</button>`);\n  if(e.status===\"reported\"&&role===\"audit_committee\") actions.push(`<button data-act=\"eng-status\" data-id=\"${esc(e.id)}\" data-status=\"closed\">完了</button>`);\n  if(canEdit) actions.push(`<button class=\"sec\" data-act=\"eng-edit\" data-id=\"${esc(e.id)}\">編集</button>`);\n  const tabs=[[\"requests\",\"証憑依頼\"],[\"workpapers\",\"監査調書\"],[\"findings\",\"指摘・是正\"]]\n    .map(([k,l])=>`<button class=\"sec ${(tab||\"requests\")===k?\"on\":\"\"}\" data-tab=\"${k}\">${l}</button>`).join(\"\");\n  let body=\"\";\n  if((tab||\"requests\")===\"workpapers\") body=workpapersHTML(d.workpapers||[], e.id, role, state.me.user);\n  else if((tab||\"requests\")===\"findings\") body=findingsHTML(d.findings||[], e.id, role);\n  else body=requestsHTMLForEng(d.requests||[], e.id, role, state.me.user);\n  return `<div class=\"card\"><h2>${esc(e.engagement_no)} ${esc(e.title)}</h2>\n    <p class=\"muted\">対象部門: ${esc(e.department)} ｜ 機密: <span class=\"badge b-purple\">${esc(e.classification)}</span> ｜\n    状態: ${badge(e.status)}</p>\n    <p><strong>目的・範囲:</strong> ${esc(e.scope)||\"—\"}</p><p><strong>評価基準:</strong> ${esc(e.criteria)||\"—\"}</p>\n    ${actions.length?`<div class=\"actions\">${actions.join(\"\")}</div>`:\"\"}\n    <div class=\"filterbar\">${tabs}</div>${body}</div>`;\n}\n\n// ===================== 証憑依頼 =====================\nfunction requestsHTML(filter){\n  const reqs=cache.requests||[];\n  const statuses=[\"draft\",\"sent\",\"partial\",\"received\",\"returned\",\"closed\"];\n  const chips=[`<button class=\"mini ${!filter?\"on\":\"\"}\" data-nav=\"requests\">すべて</button>`\n    +statuses.map(s=>`<button class=\"mini ${filter===s?\"on\":\"\"}\" data-nav=\"requests\" data-extra=\"${s}\">${stLabel(s)}</button>`).join(\"\")];\n  const rows=reqs.map(r=>`<tr class=\"clickable\" data-nav=\"engagements\" data-id=\"${esc(r.engagement_id)}\" data-tab=\"requests\">\n    <td>${esc(r.request_no)}</td><td>${esc(r.engagement_no)} ${esc(r.engagement_title||\"\")}</td>\n    <td>${esc(r.item)}</td><td>${esc(r.recipient_department)}</td>\n    <td>${badge(r.status)}</td><td>${fmtDue(r.due_at)}</td></tr>`).join(\"\");\n  return `<div class=\"card\"><h2>証憑依頼（自分の関与する依頼）</h2>\n    <p class=\"muted\">被監査部門: 自部門宛の依頼 ／ 監査側: メンバー案件の依頼。期限超過は赤字で表示します。</p>\n    <div class=\"filterbar\">${chips.join(\"\")}</div>\n    <div class=\"table-wrap\"><table><tr><th>依頼番号</th><th>案件</th><th>依頼内容</th><th>依頼先</th><th>状態</th><th>期限</th></tr>\n    ${rows||`<tr><td colspan=\"6\" class=\"muted\">依頼がありません</td></tr>`}</table></div></div>`;\n}\nfunction requestsHTMLForEng(requests,eid,role,me){\n  const isAuditee=role===\"auditee\", canCreate=role===\"auditor\"||role===\"general_affairs\";\n  const cards=requests.map(r=>{\n    const subs=r.submissions||[];\n    const btns=[];\n    if(r.status===\"draft\"&&canCreate&&!isAuditee) btns.push(`<button data-act=\"req-send\" data-id=\"${esc(r.id)}\">送付</button>`);\n    if(canCreate&&!isAuditee&&[\"sent\",\"partial\"].includes(r.status)) btns.push(`<button class=\"sec\" data-act=\"req-receive\" data-id=\"${esc(r.id)}\">全件受領</button>`);\n    if(canCreate&&!isAuditee&&[\"sent\",\"partial\",\"received\"].includes(r.status)) btns.push(`<button class=\"sec\" data-act=\"req-return\" data-id=\"${esc(r.id)}\">差戻し</button>`);\n    if(canCreate&&!isAuditee&&[\"draft\",\"sent\",\"partial\",\"received\",\"returned\"].includes(r.status)) btns.push(`<button class=\"sec\" data-act=\"req-close\" data-id=\"${esc(r.id)}\">締切</button>`);\n    if(isAuditee&&r.recipient_department===me.department&&[\"sent\",\"partial\",\"returned\"].includes(r.status)) btns.push(`<button data-act=\"evidence-submit\" data-id=\"${esc(r.id)}\">証憑を提出</button>`);\n    return `<div class=\"item-box\">\n      <div class=\"top\"><strong>${esc(r.request_no)} — ${esc(r.item)}</strong>${badge(r.status)}</div>\n      <p class=\"muted\">依頼先: ${esc(r.recipient_department)} ｜ 期限: ${fmtDue(r.due_at)} ｜ 目的: ${esc(r.purpose)||\"—\"}</p>\n      ${btns.length?`<div class=\"actions\">${btns.join(\"\")}</div>`:\"\"}\n      ${subs.length?`<div style=\"margin-top:.4rem\"><p class=\"muted\" style=\"margin:.2rem 0\">提出履歴:</p>\n        ${subs.map(s=>`<div class=\"muted\" style=\"font-size:.85rem\">📄 ${esc(s.file_name)}（記録ID: ${esc(s.content_hash.slice(0,12))}…）${dateFmt(s.submitted_at)}</div>`).join(\"\")}</div>`:\"\"}\n    </div>`;\n  }).join(\"\");\n  return `<div>\n    ${canCreate&&!isAuditee?`<div class=\"actions\"><button data-act=\"req-create\" data-id=\"${esc(eid)}\">新規依頼</button></div>`:\"\"}\n    ${cards||`<p class=\"muted\">依頼がありません</p>`}</div>`;\n}\n\n// ===================== 監査調書 =====================\nfunction workpapersHTML(wps,eid,role,me){\n  const cards=wps.map(w=>{\n    const v=w.versions||[];\n    const latest=v[0];\n    const canEdit=role===\"auditor\"&&w.owner_id===me.id&&[\"draft\",\"returned\"].includes(w.status);\n    const btns=[];\n    if(w.status!==\"final\"&&role===\"auditor\"&&w.owner_id===me.id) btns.push(`<button data-act=\"wp-review\" data-id=\"${esc(w.id)}\">レビュー依頼</button>`);\n    if(w.status===\"review_requested\"&&w.reviewer_id===me.id){\n      btns.push(`<button data-act=\"wp-approve\" data-id=\"${esc(w.id)}\">確定・署名</button>`);\n      btns.push(`<button class=\"sec\" data-act=\"wp-return\" data-id=\"${esc(w.id)}\">差戻し</button>`);\n    }\n    if(canEdit) btns.push(`<button class=\"sec\" data-act=\"wp-edit\" data-id=\"${esc(w.id)}\">編集（新版）</button>`);\n    const vers= v.length?`<details class=\"version-details\"><summary>版履歴（${v.length}件）</summary><div class=\"version-list\">${\n      v.map(x=>`<div class=\"v\">v${esc(x.version_no)} ｜ ${dateFmt(x.created_at)} ｜ ${x.is_final?\"<strong>正本</strong>\":\"草稿\"} ｜ ハッシュ: ${esc(x.content_hash.slice(0,12))}…</div>`).join(\"\")\n    }</div></details>`:\"\";\n    return `<div class=\"item-box\">\n      <div class=\"top\"><strong>${esc(w.code)} — ${esc(w.title)}</strong>${badge(w.status)}</div>\n      <p class=\"muted\">最新版: v${esc(latest?.version_no||1)}（${dateFmt(w.updated_at)}）</p>\n      <p style=\"white-space:pre-wrap;font-size:.92rem\">${esc((latest?.body||\"\").slice(0,240))}</p>\n      ${btns.length?`<div class=\"actions\">${btns.join(\"\")}</div>`:\"\"}${vers}\n    </div>`;\n  }).join(\"\");\n  return `<div>\n    ${role===\"auditor\"?`<div class=\"actions\"><button data-act=\"wp-create\" data-id=\"${esc(eid)}\">新規調書</button></div>`:\"\"}\n    ${cards||`<p class=\"muted\">調書がありません</p>`}</div>`;\n}\n\n// ===================== 指摘・是正 =====================\nfunction findingsHTML(findings,eid,role){\n  const cards=findings.map(f=>{\n    const btns=[];\n    if(![\"completed\",\"confirmed\"].includes(f.status)&&role===\"auditor\") btns.push(`<button class=\"sec\" data-act=\"fnd-confirm\" data-id=\"${esc(f.id)}\">事実確認（確定）</button>`);\n    if(f.status===\"confirmed\"&&role===\"auditee\") btns.push(`<button data-act=\"fnd-respond\" data-id=\"${esc(f.id)}\">回答</button>`);\n    if(f.status===\"confirmed\"&&role===\"auditor\") btns.push(`<button data-act=\"rem-create\" data-id=\"${esc(f.id)}\">是正計画を登録</button>`);\n    const lastResp=f.responses?.[f.responses.length-1];\n    const rems=(f.remediations||[]).map(r=>`\n      <div style=\"border-top:1px dashed var(--line);margin-top:.4rem;padding-top:.4rem\">\n        <p class=\"muted\" style=\"margin:.2rem 0\">📋 是正: ${esc(r.action)} ｜ 責任者: ${esc(ownerName(r.owner_id))} ｜ 期限: ${fmtDue(r.due_at)} ｜ 状態: ${badge(r.status)}</p>\n        ${r.status!==\"completed\"&&role===\"auditor\"?`<div class=\"actions\"><button class=\"sec\" data-act=\"rem-verify\" data-id=\"${esc(r.id)}\">再確認・完了判定</button></div>`:\"\"}\n      </div>`).join(\"\");\n    return `<div class=\"item-box\">\n      <div class=\"top\"><strong>${esc(f.finding_no)} — ${esc(f.fact.slice(0,60))}</strong>\n        <span><span class=\"badge b-purple\">重要度 ${sevLabel(f.severity)}</span> ${badge(f.status)}</span></div>\n      <p class=\"muted\">基準: ${esc(f.criterion)||\"—\"} ｜ 原因: ${esc(f.cause)||\"—\"} ｜ 影響: ${esc(f.impact)||\"—\"}</p>\n      ${lastResp?`<p class=\"muted\" style=\"font-size:.85rem\">回答: ${esc(lastResp.response)}${lastResp.disagreement?`（異議: ${esc(lastResp.disagreement)}）`:\"\"}</p>`:\"\"}\n      ${btns.length?`<div class=\"actions\">${btns.join(\"\")}</div>`:\"\"}${rems}\n    </div>`;\n  }).join(\"\");\n  return `<div>\n    ${role===\"auditor\"?`<div class=\"actions\"><button data-act=\"fnd-create\" data-id=\"${esc(eid)}\">新規指摘</button></div>`:\"\"}\n    ${cards||`<p class=\"muted\">指摘がありません</p>`}</div>`;\n}\nfunction ownerName(uid){ const u=cache.users.find(x=>x.id===uid); return u?`${u.name}（${u.department}）`:uid.slice(0,12); }\n\n// ===================== 監査ログ =====================\nfunction auditLogHTML(){\n  const events=cache.events||[];\n  const usersOpts=cache.users.map(u=>`<option value=\"${esc(u.id)}\">${esc(u.name)}（${esc(u.department)}）</option>`).join(\"\");\n  const actionKeys=Object.keys(ACTION_JA);\n  const rows=events.map(ev=>{\n    const actor=cache.users.find(u=>u.id===ev.actor_id);\n    const rawAction=ev.action.startsWith(\"permission_denied\")?\"permission_denied\":ev.action;\n    return `<tr><td>${dateFmt(ev.occurred_at)}</td>\n      <td>${actor?`${esc(actor.name)}（${esc(actor.department)}）`:(ev.actor_id?esc(ev.actor_id.slice(0,14)):\"—\")}</td>\n      <td>${ACTION_JA[rawAction]||esc(ev.action)}${ev.action!==rawAction?` <span class=\"muted\">(${esc(ev.action.split(\":\")[1])})</span>`:\"\"}</td>\n      <td>${OBJ_JA[ev.object_type]||esc(ev.object_type)}/${esc(ev.object_id.slice(0,16))}</td>\n      <td>${RESULT_JA[ev.result]||esc(ev.result)}</td>\n      <td>${esc(ev.detail)}</td><td class=\"muted\">${esc(ev.ip)}</td></tr>`;\n  }).join(\"\");\n  return `<div class=\"card\"><h2>監査ログ（追記専用）</h2>\n    <div class=\"filterbar\">\n      <select id=\"log-actor\" style=\"max-width:220px\"><option value=\"\">操作者（すべて）</option>${usersOpts}</select>\n      <select id=\"log-action\" style=\"max-width:200px\"><option value=\"\">操作（すべて）</option>${actionKeys.map(k=>`<option value=\"${esc(k)}\">${ACTION_JA[k]}</option>`).join(\"\")}</select>\n      <select id=\"log-obj\" style=\"max-width:180px\"><option value=\"\">対象（すべて）</option>${Object.entries(OBJ_JA).map(([k,v])=>`<option value=\"${k}\">${v}</option>`).join(\"\")}</select>\n      <select id=\"log-limit\" style=\"max-width:120px\"><option value=\"100\">100件</option><option value=\"200\">200件</option><option value=\"500\">500件</option></select>\n      <button data-act=\"log-apply\">絞り込み</button>\n    </div>\n    <div class=\"table-wrap\"><table><tr><th>日時</th><th>操作者</th><th>操作</th><th>対象</th><th>結果</th><th>詳細</th><th>IP</th></tr>\n    ${rows||`<tr><td colspan=\"7\" class=\"muted\">ログがありません</td></tr>`}</table></div></div>`;\n}\n\nfunction loadingCard(){ return `<div class=\"card\"><h2>読み込み中…</h2><p class=\"muted\">データを取得しています。</p></div>`; }\n\n// ===================== ログイン =====================\nfunction renderLogin(){\n  app.innerHTML=`<main class=\"login-wrap\"><div class=\"login-box\">\n    <h2>🧭 監査業務・証跡管理</h2>\n    <p class=\"muted\">ログインして監査の計画・証憑・調書・指摘・改善確認を管理します。</p>\n    <label>メールアドレス</label><input id=\"le\" type=\"email\" autocomplete=\"username\">\n    <label>パスワード</label><input id=\"lp\" type=\"password\" autocomplete=\"current-password\">\n    <p class=\"error\" id=\"lerr\"></p>\n    <div class=\"actions\"><button id=\"login-btn\">ログイン</button></div>\n    <p class=\"hint\" id=\"hint\" style=\"display:none\">テスト用: auditor@mirai.local / Mirai@2026pass（committee / ga / kensetsu / zaimu / admin も同様）</p>\n  </div></main>`;\n  const doLogin=async()=>{\n    try{ await A.login(document.getElementById(\"le\").value, document.getElementById(\"lp\").value); state.me=await A.me(); navigate(\"home\"); render(); }\n    catch(e){ const el=document.getElementById(\"lerr\"); if(el) el.textContent=e.message; }\n  };\n  document.getElementById(\"login-btn\").onclick=doLogin;\n  document.getElementById(\"lp\").addEventListener(\"keydown\",e=>{ if(e.key===\"Enter\") doLogin(); });\n  A.health().then(h=>{ if(h?.environment!==\"production\"){ const el=document.getElementById(\"hint\"); if(el) el.style.display=\"\"; } }).catch(()=>{});\n}\n\n// ===================== アクション =====================\nfunction refreshRoute(){ render(); }\n\nasync function runAction(act){\n  const a=act.dataset.act, id=act.dataset.id||null;\n  try{\n    switch(a){\n      case \"hamburger\": {\n        const sb=document.getElementById(\"sidebar\"), bd=document.getElementById(\"side-backdrop\");\n        sb?.classList.toggle(\"open\"); bd?.classList.toggle(\"show\"); break;\n      }\n      case \"collapse-sidebar\": {\n        const sb=document.getElementById(\"sidebar\");\n        const collapsed=sb?.classList.toggle(\"collapsed\");\n        localStorage.setItem(\"maw.sidebar.collapsed\", collapsed?\"1\":\"0\"); break;\n      }\n      case \"logout\": await A.logout(); state.me=null; navigate(\"home\"); render(); toast(\"ログアウトしました\"); break;\n      case \"password\": openPasswordModal(); break;\n\n      // ---- 監査計画 ----\n      case \"plan-create\": openPlanForm(null); break;\n      case \"plan-edit\": { const p=cache.planDetail?.plan; if(p) openPlanForm(p); break; }\n      case \"plan-submit\": confirmModal(\"承認申請を提出します。よろしいですか？\", async()=>{ await A.submitPlan(id); toast(\"承認申請しました\"); refreshRoute(); }); break;\n      case \"plan-approve\": confirmModal(\"この計画を承認します。よろしいですか？\", async()=>{ await A.approvePlan(id); toast(\"承認しました\"); refreshRoute(); }); break;\n      case \"plan-reject\": confirmModal(\"この計画を却下します。よろしいですか？\", async()=>{ await A.rejectPlan(id); toast(\"却下しました\"); refreshRoute(); }); break;\n\n      // ---- 監査案件 ----\n      case \"eng-create\": openEngForm(null); break;\n      case \"eng-edit\": { const e=cache.engDetail?.engagement; if(e) openEngForm(e); break; }\n      case \"eng-status\": confirmModal(`案件状態を「${stLabel(act.dataset.status)}」へ変更します。よろしいですか？`, async()=>{ await A.setEngStatus(id, act.dataset.status); toast(\"状態を更新しました\"); refreshRoute(); }); break;\n      case \"eng-filter\": cache.engFilter=act.dataset.status||null; render(); break;\n\n      // ---- 証憑依頼 ----\n      case \"req-create\": openReqForm(id); break;\n      case \"req-send\": confirmModal(\"依頼を被監査部門へ送付します。よろしいですか？\", async()=>{ await A.sendRequest(id); toast(\"送付しました\"); refreshRoute(); }); break;\n      case \"req-receive\": confirmModal(\"証憑を全件受領します。よろしいですか？\", async()=>{ await A.receiveRequest(id); toast(\"受領しました\"); refreshRoute(); }); break;\n      case \"req-return\": confirmModal(\"この依頼を差し戻します。よろしいですか？\", async()=>{ await A.returnRequest(id); toast(\"差し戻しました\"); refreshRoute(); }); break;\n      case \"req-close\": confirmModal(\"この依頼を締め切ります。よろしいですか？\", async()=>{ await A.closeRequest(id); toast(\"締め切りました\"); refreshRoute(); }); break;\n      case \"evidence-submit\": openEvidenceForm(id); break;\n\n      // ---- 監査調書 ----\n      case \"wp-create\": openWpForm(id,null); break;\n      case \"wp-edit\": { const w=(cache.engDetail?.workpapers||[]).find(x=>x.id===id); if(w) openWpForm(id,w); break; }\n      case \"wp-review\": confirmModal(\"レビューを依頼します。よろしいですか？\", async()=>{ await A.reqReview(id); toast(\"レビューを依頼しました\"); refreshRoute(); }); break;\n      case \"wp-approve\": confirmModal(\"この調書を確定（正本）とします。よろしいですか？\", async()=>{ await A.approveWorkpaper(id); toast(\"確定しました\"); refreshRoute(); }); break;\n      case \"wp-return\": confirmModal(\"この調書を差し戻します。よろしいですか？\", async()=>{ await A.returnWorkpaper(id); toast(\"差し戻しました\"); refreshRoute(); }); break;\n\n      // ---- 指摘・是正 ----\n      case \"fnd-create\": openFndForm(id); break;\n      case \"fnd-confirm\": confirmModal(\"指摘の事実確認（確定）を行います。よろしいですか？\", async()=>{ await A.confirmFinding(id,{}); toast(\"確定しました\"); refreshRoute(); }); break;\n      case \"fnd-respond\": openRespForm(id); break;\n      case \"rem-create\": openRemForm(id); break;\n      case \"rem-verify\": openVerifyForm(id); break;\n\n      // ---- 監査ログ ----\n      case \"log-apply\": {\n        const p=new URLSearchParams();\n        const actor=document.getElementById(\"log-actor\")?.value, act2=document.getElementById(\"log-action\")?.value,\n              obj=document.getElementById(\"log-obj\")?.value, lim=document.getElementById(\"log-limit\")?.value;\n        if(actor) p.set(\"actor_id\",actor); if(act2) p.set(\"action\",act2); if(obj) p.set(\"object_type\",obj); if(lim) p.set(\"limit\",lim);\n        const seq=renderSeq;\n        const ev=await A.auditEvents(p.toString()); if(seq===renderSeq){ cache.events=ev.events; render(); }\n        break;\n      }\n      default: break;\n    }\n  }catch(e){ toast(e.message,\"err\"); }\n}\n\n// ===================== フォーム（モーダル） =====================\nfunction openPasswordModal(){\n  openModal({title:\"パスワード変更\",okLabel:\"変更する\",body:`\n    <label>現在のパスワード</label><input id=\"pw-cur\" type=\"password\" autocomplete=\"current-password\">\n    <label>新しいパスワード（8文字以上・英字と数字を含む）</label><input id=\"pw-new\" type=\"password\" autocomplete=\"new-password\">\n    <label>新しいパスワード（確認）</label><input id=\"pw-new2\" type=\"password\" autocomplete=\"new-password\">`,\n    onOk:async(btn)=>{\n      const cur=document.getElementById(\"pw-cur\").value, n1=document.getElementById(\"pw-new\").value, n2=document.getElementById(\"pw-new2\").value;\n      if(!cur||!n1){modalErr(\"すべての項目を入力してください\");return;}\n      if(n1!==n2){modalErr(\"新しいパスワードが一致しません\");return;}\n      if(!/^(?=.*[A-Za-z])(?=.*\\d).{8,}$/.test(n1)){modalErr(\"8文字以上で英字と数字をそれぞれ1文字以上含めてください\");return;}\n      btn.disabled=true;\n      try{ await A.changePassword(cur,n1); closeModal(); toast(\"パスワードを変更しました\"); }\n      catch(e){ modalErr(e.message); btn.disabled=false; }\n    }});\n}\nfunction openPlanForm(p){\n  openModal({title:p?\"計画の編集\":\"新規監査計画\",okLabel:p?\"保存\":\"作成\",body:`\n    <div class=\"row\"><div><label>年度（西暦4桁）</label><input id=\"pfy\" value=\"${p?esc(p.fiscal_year):new Date().getFullYear()}\"></div>\n    <div><label>計画名</label><input id=\"ptitle\" value=\"${p?esc(p.title):\"\"}\"></div></div>\n    <label>方針・重点領域</label><textarea id=\"ppolicy\" rows=\"3\">${p?esc(p.policy):\"\"}</textarea>`,\n    onOk:async(btn)=>{\n      const d={fiscal_year:document.getElementById(\"pfy\").value.trim(),title:document.getElementById(\"ptitle\").value.trim(),policy:document.getElementById(\"ppolicy\").value.trim()};\n      if(!/^\\d{4}$/.test(d.fiscal_year)){modalErr(\"年度は西暦4桁で入力してください\");return;}\n      if(!d.title){modalErr(\"計画名は必須です\");return;}\n      btn.disabled=true;\n      try{ if(p) await A.updatePlan(p.id,d); else await A.createPlan(d); closeModal(); toast(\"保存しました\"); refreshRoute(); }\n      catch(e){ modalErr(e.message); btn.disabled=false; }\n    }});\n}\nasync function ensureUsers(){ if(cache.users.length) return; try{ const r=await A.users(); cache.users=r.users||[]; }catch{ /* 権限なし等は無視 */ } }\nfunction userOptions(roles){\n  const us=cache.users.filter(u=>!roles||roles.includes(u.role));\n  return us.map(u=>`<option value=\"${esc(u.id)}\">${esc(u.name)}（${esc(u.department)} / ${ROLE[u.role]||esc(u.role)}）</option>`).join(\"\");\n}\nfunction openEngForm(e){\n  const plansOpts=cache.plans.map(p=>`<option value=\"${esc(p.id)}\" ${e&&e.plan_id===p.id?\"selected\":\"\"}>${esc(p.fiscal_year)} ${esc(p.title)}</option>`).join(\"\");\n  openModal({title:e?\"案件の編集\":\"新規監査案件\",okLabel:e?\"保存\":\"作成\",wide:true,body:`\n    ${e?\"\":`<label>対象計画</label><select id=\"eplan\">${plansOpts}</select>`}\n    <div class=\"row\"><div><label>案件名</label><input id=\"etitle\" value=\"${e?esc(e.title):\"\"}\"></div>\n    <div><label>対象部門</label><input id=\"edept\" value=\"${e?esc(e.department):\"\"}\"></div>\n    <div><label>機密区分</label><select id=\"eclass\"><option value=\"C1\" ${e&&e.classification===\"C1\"?\"selected\":\"\"}>C1 社内</option><option value=\"C2\" ${!e||e.classification===\"C2\"?\"selected\":\"\"}>C2 監査限定</option><option value=\"C3\" ${e&&e.classification===\"C3\"?\"selected\":\"\"}>C3 特別機密</option></select></div></div>\n    <label>目的・範囲</label><textarea id=\"escope\" rows=\"2\">${e?esc(e.scope):\"\"}</textarea>\n    <label>評価基準</label><textarea id=\"ecrit\" rows=\"2\">${e?esc(e.criteria):\"\"}</textarea>`,\n    onOk:async(btn)=>{\n      const title=document.getElementById(\"etitle\").value.trim(), dept=document.getElementById(\"edept\").value.trim();\n      if(!title||!dept){modalErr(\"案件名と対象部門は必須です\");return;}\n      const d={title,department:dept,classification:document.getElementById(\"eclass\").value,scope:document.getElementById(\"escope\").value.trim(),criteria:document.getElementById(\"ecrit\").value.trim()};\n      btn.disabled=true;\n      try{\n        if(e){ await A.updateEngagement(e.id,d); }\n        else { const planId=document.getElementById(\"eplan\")?.value; if(!planId){modalErr(\"対象計画を選択してください\");btn.disabled=false;return;} d.plan_id=planId; await A.createEngagement(d); }\n        closeModal(); toast(\"保存しました\"); refreshRoute();\n      }catch(err){ modalErr(err.message); btn.disabled=false; }\n    }});\n}\nfunction openReqForm(eid){\n  openModal({title:\"新規証憑依頼\",okLabel:\"作成\",body:`\n    <div class=\"row\"><div><label>依頼先部門</label><input id=\"rdept\"></div>\n    <div><label>期限</label><input id=\"rdue\" type=\"date\"></div></div>\n    <label>依頼内容</label><textarea id=\"ritem\" rows=\"2\"></textarea>\n    <label>目的</label><input id=\"rpurpose\">\n    <p class=\"hint\">現時点では依頼の記録と状態管理のみです（メール等の通知は未実装。受入試験前に通知機能の実装を推奨）。</p>`,\n    onOk:async(btn)=>{\n      const item=document.getElementById(\"ritem\").value.trim(), dept=document.getElementById(\"rdept\").value.trim();\n      if(!item||!dept){modalErr(\"依頼内容と依頼先部門は必須です\");return;}\n      btn.disabled=true;\n      try{ await A.createRequest(eid,{recipient_department:dept,item,purpose:document.getElementById(\"rpurpose\").value.trim(),due_at:document.getElementById(\"rdue\").value||null}); closeModal(); toast(\"依頼を作成しました\"); refreshRoute(); }\n      catch(e){ modalErr(e.message); btn.disabled=false; }\n    }});\n}\nfunction openEvidenceForm(rid){\n  openModal({title:\"証憑を提出\",okLabel:\"提出する\",body:`\n    <label>ファイル名</label><input id=\"sf\">\n    <label>補足</label><input id=\"sn\">\n    <p class=\"hint\">現行MVPはファイルの実アップロード未対応のため、ファイル名と記録ID（ハッシュ）を記録します。実ファイル保存・検証（R2 + SHA-256）は受入試験前に実装予定です（評価レポート F-05）。</p>`,\n    onOk:async(btn)=>{\n      const fn=document.getElementById(\"sf\").value.trim();\n      if(!fn){modalErr(\"ファイル名は必須です\");return;}\n      const note=document.getElementById(\"sn\").value.trim();\n      const buf=await crypto.subtle.digest(\"SHA-256\", new TextEncoder().encode(fn+note+Date.now()));\n      const hash=[...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,\"0\")).join(\"\");\n      btn.disabled=true;\n      try{ await A.submitEvidence(rid,{file_name:fn,content_hash:hash,note}); closeModal(); toast(\"提出しました\"); refreshRoute(); }\n      catch(e){ modalErr(e.message); btn.disabled=false; }\n    }});\n}\nasync function openWpForm(eid,w){\n  await ensureUsers();\n  openModal({title:w?\"調書の編集（新版として保存）\":\"新規監査調書\",okLabel:w?\"新版を保存\":\"作成\",wide:true,body:`\n    ${w?\"\":`<div class=\"row\"><div><label>調書コード</label><input id=\"wcode\"></div>\n    <div><label>調書名</label><input id=\"wtitle\"></div></div>`}\n    <label>実施内容</label><textarea id=\"wbody\" rows=\"5\">${w?esc(w.versions?.[0]?.body||\"\"):\"\"}</textarea>\n    <label>結論</label><textarea id=\"wconc\" rows=\"3\">${w?esc(w.versions?.[0]?.conclusion||\"\"):\"\"}</textarea>\n    ${w?\"\":`<label>レビュー担当者（作成者と分離が必要）</label><select id=\"wrev\"><option value=\"\">未指定</option>${userOptions([\"auditor\",\"audit_committee\"])}</select>`}`,\n    onOk:async(btn)=>{\n      btn.disabled=true;\n      try{\n        if(w){\n          await A.updateWorkpaper(w.id,{body:document.getElementById(\"wbody\").value,conclusion:document.getElementById(\"wconc\").value});\n        }else{\n          const code=document.getElementById(\"wcode\").value.trim(), title=document.getElementById(\"wtitle\").value.trim();\n          if(!code||!title){modalErr(\"調書コードと調書名は必須です\");btn.disabled=false;return;}\n          const reviewer=document.getElementById(\"wrev\")?.value||null;\n          if(reviewer===state.me.user.id){modalErr(\"作成者とレビュー者を分離してください\");btn.disabled=false;return;}\n          await A.createWorkpaper(eid,{code,title,body:document.getElementById(\"wbody\").value,conclusion:document.getElementById(\"wconc\").value,reviewer_id:reviewer});\n        }\n        closeModal(); toast(\"保存しました\"); refreshRoute();\n      }catch(e){ modalErr(e.message); btn.disabled=false; }\n    }});\n}\nfunction openFndForm(eid){\n  openModal({title:\"新規指摘\",okLabel:\"作成\",body:`\n    <label>事実</label><textarea id=\"ffact\" rows=\"2\"></textarea>\n    <div class=\"row\"><div><label>評価基準</label><input id=\"fcrit\"></div>\n    <div><label>重要度</label><select id=\"fsev\"><option value=\"high\">高</option><option value=\"medium\" selected>中</option><option value=\"low\">低</option></select></div></div>\n    <label>原因</label><input id=\"fcause\"><label>影響</label><input id=\"fimpact\">`,\n    onOk:async(btn)=>{\n      const fact=document.getElementById(\"ffact\").value.trim();\n      if(!fact){modalErr(\"事実は必須です\");return;}\n      btn.disabled=true;\n      try{ await A.createFinding(eid,{fact,criterion:document.getElementById(\"fcrit\").value.trim(),cause:document.getElementById(\"fcause\").value.trim(),impact:document.getElementById(\"fimpact\").value.trim(),severity:document.getElementById(\"fsev\").value}); closeModal(); toast(\"指摘を作成しました\"); refreshRoute(); }\n      catch(e){ modalErr(e.message); btn.disabled=false; }\n    }});\n}\nfunction openRespForm(fid){\n  openModal({title:\"指摘への回答\",okLabel:\"回答を提出\",body:`\n    <label>回答・見解</label><textarea id=\"rr\" rows=\"3\"></textarea>\n    <label>異議（あれば）</label><input id=\"rd\">`,\n    onOk:async(btn)=>{\n      const response=document.getElementById(\"rr\").value.trim();\n      if(!response){modalErr(\"回答は必須です\");return;}\n      btn.disabled=true;\n      try{ await A.respondFinding(fid,{response,disagreement:document.getElementById(\"rd\").value.trim()}); closeModal(); toast(\"回答を提出しました\"); refreshRoute(); }\n      catch(e){ modalErr(e.message); btn.disabled=false; }\n    }});\n}\nasync function openRemForm(fid){\n  await ensureUsers();\n  openModal({title:\"是正計画を登録\",okLabel:\"登録\",body:`\n    <label>是正内容</label><textarea id=\"ra\" rows=\"3\"></textarea>\n    <div class=\"row\"><div><label>是正責任者（選択）</label><select id=\"ro\">${userOptions()}</select></div>\n    <div><label>期限</label><input id=\"rd\" type=\"date\"></div></div>`,\n    onOk:async(btn)=>{\n      const action=document.getElementById(\"ra\").value.trim(), owner=document.getElementById(\"ro\").value;\n      if(!action){modalErr(\"是正内容は必須です\");return;}\n      if(!owner){modalErr(\"是正責任者を選択してください\");return;}\n      btn.disabled=true;\n      try{ await A.createRemediation(fid,{action,owner_id:owner,due_at:document.getElementById(\"rd\").value||null}); closeModal(); toast(\"是正計画を登録しました\"); refreshRoute(); }\n      catch(e){ modalErr(e.message); btn.disabled=false; }\n    }});\n}\nfunction openVerifyForm(rid){\n  openModal({title:\"再確認・完了判定\",okLabel:\"判定する\",body:`\n    <label>再確認結果</label><input id=\"vr\">\n    <label>完了証憑</label><input id=\"ve\">\n    <p class=\"hint\">完了・継続監視・再指摘の最終判断は監査役が行います（本操作は完了として記録します）。</p>`,\n    onOk:async(btn)=>{\n      const result=document.getElementById(\"vr\").value.trim();\n      if(!result){modalErr(\"再確認結果は必須です\");return;}\n      btn.disabled=true;\n      try{ await A.verifyRemediation(rid,{result,evidence_note:document.getElementById(\"ve\").value.trim()}); closeModal(); toast(\"判定を記録しました\"); refreshRoute(); }\n      catch(e){ modalErr(e.message); btn.disabled=false; }\n    }});\n}\n\n// ===================== イベント委譲（1箇所で全て処理） =====================\ndocument.addEventListener(\"click\", e=>{\n  const navEl=e.target.closest(\"[data-nav]\");\n  if(navEl){ e.preventDefault();\n    if(navEl.dataset.nav===\"requests\"&&navEl.dataset.extra) navigate(\"requests\",null,null,navEl.dataset.extra);\n    else navigate(navEl.dataset.nav, navEl.dataset.id||null, navEl.dataset.tab||null);\n    return; }\n  const tabEl=e.target.closest(\"[data-tab]\");\n  if(tabEl){ const r=parseHash(); if(r.id){ navigate(\"engagements\", r.id, tabEl.dataset.tab); } return; }\n  const modalEl=e.target.closest(\"[data-modal]\");\n  if(modalEl){ closeModal(); return; }\n  const actEl=e.target.closest(\"[data-act]\");\n  if(actEl){ e.preventDefault(); runAction(actEl); return; }\n});\nwindow.addEventListener(\"hashchange\", ()=>{ closeModal(); render(); });\n\n// ===================== 起動 =====================\nrefreshMe();\n</script>\n</body>\n</html>\n";
